WHERE h.measured_at >= #{start} AND h.measured_at < #{end}
AND e.region_id=#{regionId}
AND h.elder_id=#{elderId}

WHERE p.due_at >= #{start} AND p.due_at < #{end}
  AND (p.canceled_at IS NULL OR p.canceled_at >= #{cutoff})
AND e.region_id=#{regionId}
AND p.doctor_id=#{doctorId}
AND p.elder_id=#{elderId}
